"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisPricingContent } from "./components/pricing/content";
import View0 from "./components/pricing/variants/01-ai";
const views={"ai":View0};
export type { ArtemisPricingBenefits, ArtemisPricingBilling, ArtemisPricingCalculator, ArtemisPricingContent, ArtemisPricingImage, ArtemisPricingLink, ArtemisPricingPlan, ArtemisPricingTier } from "./components/pricing/content";
export interface ArtemisPricingProps {className?:string;variant?:"ai";/** The words on the pricing section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisPricingContent>;}
export function ArtemisPricing({className,variant="ai",content}:ArtemisPricingProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisPricingLink {
  label: string;
  href: string;
}

/** A picture shown as content. */
export interface ArtemisPricingImage {
  src: string;
  alt: string;
}

/** The two options of the billing switch. */
export interface ArtemisPricingBilling {
  /** The monthly option. */
  monthly: string;
  /** The yearly option. */
  yearly: string;
  /** What paying yearly saves, such as "Save 20%". command-deck and ledger add it to the yearly option, plans-grid shows it beside it. ledger's estimate takes 20% off whatever this says. */
  saving?: string;
}

/** A usage level of a plan, with its own price. */
export interface ArtemisPricingTier {
  /** The tier's option in the plan's switch, such as "5x". */
  label: string;
  /** Replaces the plan's `price` while the tier is chosen. */
  price?: number;
  /** Replaces the plan's `yearlyPrice` while the tier is chosen. */
  yearlyPrice?: number;
  /** Replaces the plan's `description` while the tier is chosen. */
  description?: string;
  /** Replaces the plan's `cta` while the tier is chosen. */
  cta?: ArtemisPricingLink;
}

/** A plan and its price. */
export interface ArtemisPricingPlan {
  /** A short id such as "pro". shared-benefits uses it as the plan picker's value, or the name when left out. */
  id?: string;
  /** All layouts. */
  name: string;
  /** Who the plan is for. All layouts but aurora-flow. */
  description?: string;
  /** The price per month, or the one-off price, as a number of `currency`. All layouts; ledger adds seats to it. */
  price?: number;
  /** The price per month when billed yearly. ai, shared-benefits, command-deck and plans-grid show it while yearly is chosen, and keep `price` without it. */
  yearlyPrice?: number;
  /** Words shown instead of the price, such as "Free" or "Custom pricing". All layouts. */
  priceLabel?: string;
  /** An earlier price, struck through beside the price. plans-grid. */
  compareAtPrice?: number;
  /** After the price, such as "/ month" or "one time". All layouts. */
  period?: string;
  /** A short line about the price, such as "Billed monthly": under the price in ai, shared-benefits and command-deck, at the foot of the card in plans-grid. With `yearlyNote`, it shows only while monthly is chosen. */
  note?: string;
  /** The line in place of `note` while yearly is chosen, such as "{total} billed yearly"; "{total}" becomes the yearly total with its currency. ai, shared-benefits, command-deck and plans-grid. */
  yearlyNote?: string;
  /** A small tag beside the name, such as "Best value". aurora-flow, visual-plans and plans-grid. */
  badge?: string;
  /** Marks the plan to recommend. ai, visual-plans, command-deck and plans-grid draw it apart; shared-benefits and ledger open on it; aurora-flow shows it. */
  featured?: boolean;
  /** A small heading over the features. ai and visual-plans. */
  featuresTitle?: string;
  /** What the plan includes. All layouts; shared-benefits lists them on one line. */
  features: string[];
  /** The plan's button. All layouts; shared-benefits and ledger show the chosen plan's. "{billing}" in the href becomes the chosen period, "monthly" or "annual" ("yearly" in shared-benefits; always "monthly" in layouts without a switch). */
  cta: ArtemisPricingLink;
  /** Usage levels with their own price, shown as a switch on the plan. ai. */
  tiers?: ArtemisPricingTier[];
  /** Seats the price includes. ledger. */
  includedSeats?: number;
  /** The monthly price of each seat after `includedSeats`. ledger. */
  seatPrice?: number;
}

/** What every plan includes. */
export interface ArtemisPricingBenefits {
  /** A small line over the title. */
  badge?: string;
  title: string;
  items: string[];
}

/** The words on ledger's seat calculator and estimate. The maths stays in the layout. */
export interface ArtemisPricingCalculator {
  /** Before each plan's price in the plan picker, such as "From". */
  from: string;
  /** Before the chosen plan's name, over its details, such as "Selected". */
  selected: string;
  /** After the chosen plan's price, such as "/ base". */
  base: string;
  /** Over the seat count, such as "Team size". */
  teamSize: string;
  /** After the seat count, such as "seats". */
  seats: string;
  /** After the seats a plan includes, such as "included". */
  included: string;
  /** After the price of each extra seat, such as "thereafter". */
  thereafter: string;
  /** Before the chosen plan's name, over the estimate, such as "Estimate". */
  estimate: string;
  /** A tag under the estimate's title, such as "Updates live". */
  live: string;
  /** The estimate's line for the plan's price, such as "Base plan". */
  basePlan: string;
  /** After the number of included seats, such as "included seats". */
  includedSeats: string;
  /** After the number of extra seats, such as "additional seats". */
  extraSeats: string;
  /** The estimate's line for the yearly discount, such as "Annual discount". */
  discount: string;
  /** Over the total, such as "Due monthly". */
  total: string;
  /** After the total, such as "USD". */
  currencyCode: string;
}

/** The words on an Artemis pricing section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisPricingContent {
  /** A short line over the headline. ai, aurora-flow, visual-plans, command-deck, ledger and plans-grid. */
  badge?: string;
  /** All layouts. */
  headline: string;
  /** A sentence or two under the headline. All layouts but ledger. */
  subhead?: string;
  /** The sign before every price, such as "$". All layouts. */
  currency: string;
  /** The billing switch. ai, shared-benefits, command-deck, ledger and plans-grid. */
  billing?: ArtemisPricingBilling;
  /** All layouts. aurora-flow shows the featured plan, or the first; visual-plans looks best with two, the others with three. */
  plans: ArtemisPricingPlan[];
  /** A heading over the plan picker. shared-benefits. */
  plansTitle?: string;
  /** What every plan includes, beside the plan picker. shared-benefits. */
  benefits?: ArtemisPricingBenefits;
  /** The picture over the benefits. shared-benefits. */
  image?: ArtemisPricingImage;
  /** A line of small print: under the plans in ai and plans-grid, under the subhead in aurora-flow, under the button in ledger. */
  footnote?: string;
  /** The words on the seat calculator. ledger. */
  calculator?: ArtemisPricingCalculator;
}

